    File tmpFile = context.getTempFile();
    EntityType.PROCESS.getMarshaller().marshal(process, tmpFile);
    context.scheduleProcess(tmpFile.getAbsolutePath(), overlay);
    context.waitForBundleStart(Status.FAILED);
    //Delete and re-submit the process with correct workflow
    ClientResponse clientRepsonse = context.service.path("api/entities/delete/process/" + context.processName).header("Remote-User", TestContext.REMOTE_USER).accept(MediaType.TEXT_XML).delete(ClientResponse.class);
    context.assertSuccessful(clientRepsonse);
    process.getWorkflow().setPath("/falcon/test/workflow");
    tmpFile = context.getTempFile();
    EntityType.PROCESS.getMarshaller().marshal(process, tmpFile);
    clientRepsonse = context.service.path("api/entities/submitAndSchedule/process").header("Remote-User", TestContext.REMOTE_USER).accept(MediaType.TEXT_XML).type(MediaType.TEXT_XML).post(ClientResponse.class, context.getServletInputStream(tmpFile.getAbsolutePath()));
    context.assertSuccessful(clientRepsonse);
    //Assert that new schedule creates new bundle
    List<BundleJob> bundles = context.getBundles();
    Assert.assertEquals(bundles.size(), 2);
}

