@Test
public void testDelete() throws Exception {
    TestContext context = newContext();
    ClientResponse response;
    Map<String, String> overlay = context.getUniqueOverlay();
    response = context.submitToFalcon(context.CLUSTER_TEMPLATE, overlay, EntityType.CLUSTER);
    context.assertSuccessful(response);
    response = context.submitToFalcon(TestContext.FEED_TEMPLATE1, overlay, EntityType.FEED);
    context.assertSuccessful(response);
    response = context.service.path("api/entities/delete/cluster/" + context.clusterName).header("Remote-User", TestContext.REMOTE_USER).accept(MediaType.TEXT_XML).delete(ClientResponse.class);
    context.assertFailure(response);
    response = context.submitToFalcon(TestContext.FEED_TEMPLATE2, overlay, EntityType.FEED);
    context.assertSuccessful(response);
    response = context.submitToFalcon(TestContext.PROCESS_TEMPLATE, overlay, EntityType.PROCESS);
    context.assertSuccessful(response);
    //Delete a referred feed
    response = context.service.path("api/entities/delete/feed/" + overlay.get("inputFeedName")).header("Remote-User", TestContext.REMOTE_USER).accept(MediaType.TEXT_XML).delete(ClientResponse.class);
    context.assertFailure(response);
    //Delete a submitted process
    response = context.service.path("api/entities/delete/process/" + context.processName).header("Remote-User", TestContext.REMOTE_USER).accept(MediaType.TEXT_XML).delete(ClientResponse.class);
    context.assertSuccessful(response);
    response = context.submitToFalcon(TestContext.PROCESS_TEMPLATE, overlay, EntityType.PROCESS);
    context.assertSuccessful(response);
    ClientResponse clientRepsonse = context.service.path("api/entities/schedule/process/" + context.processName).header("Remote-User", TestContext.REMOTE_USER).accept(MediaType.TEXT_XML).type(MediaType.TEXT_XML).post(ClientResponse.class);
    context.assertSuccessful(clientRepsonse);
    //Delete a scheduled process
    response = context.service.path("api/entities/delete/process/" + context.processName).header("Remote-User", TestContext.REMOTE_USER).accept(MediaType.TEXT_XML).delete(ClientResponse.class);
    context.assertSuccessful(response);
}

